func:
const interval_ms = Number(env.get('OPCUA_SUB_INTERVAL_MS') || 1000);
const line_ids = ['LINE-01', 'LINE-02', 'LINE-03'];
const equipment_ids = ['CAST-01', 'CNC-01', 'CNC-02', 'CNC-03', 'WASH-01', 'ASSY-01', 'ASSY-02', 'TEST-01', 'TEST-02'];
const sensor_fields = [
  ['vibration_rms', 'Double'],
  ['current_a', 'Double'],
  ['voltage_v', 'Double'],
  ['equipment_temperature_c', 'Double']
];

function to_node_token(value) {
  return String(value).replace(/[^A-Za-z0-9_]/g, '_');
}

const outputs = [[], [], [], []];

for (const [line_index, line_id] of line_ids.entries()) {
  for (const equipment_id of equipment_ids) {
    const source_node_id = `ns=2;s=${line_id}.${equipment_id}.payload`;
    outputs[line_index].push({
      payload: interval_ms,
      interval: interval_ms,
      topic: `${source_node_id};datatype=String`,
      collect_type: 'line_payload',
      line_id,
      equipment_id,
      source_node_id,
      datatype: 'String'
    });
  }
}

for (const line_id of line_ids) {
  for (const equipment_id of equipment_ids) {
    const source_line = to_node_token(line_id);
    const source_equipment = to_node_token(equipment_id);
    for (const [sensor_field, datatype] of sensor_fields) {
      const source_node_id = `ns=1;s=DAS_${source_line}_${source_equipment}_${sensor_field}`;
      outputs[3].push({
        payload: interval_ms,
        interval: interval_ms,
        topic: `${source_node_id};datatype=${datatype}`,
        collect_type: 'sensor_leaf',
        line_id,
        equipment_id,
        sensor_field,
        source_node_id,
        datatype
      });
    }
  }
}

node.status({
  fill: 'blue',
  shape: 'dot',
  text: `collect subs line=${outputs[0].length + outputs[1].length + outputs[2].length}, sensor=${outputs[3].length}`
});

return outputs;

const source_node_id = msg.topic || msg.nodeId || msg.source_node_id || '';
const source_match = source_node_id.match(/LINE-(\d{2})\.([A-Z]+-\d{2})\.payload$/);

let collect_line_name = null;
let collect_equipment_name = null;
if (source_match) {
  collect_line_name = `LINE-${source_match[1]}`;
  collect_equipment_name = source_match[2];
}

msg.topic = 'collect/line_payload';
msg.payload = {
  collect_type: 'line_payload',
  collect_line_name,
  collect_equipment_name,
  source_node_id,
  datatype: msg.datatype || null,
  raw_payload: msg.payload,
  source_timestamp: msg.sourceTimestamp || msg.source_timestamp || null,
  server_timestamp: msg.serverTimestamp || msg.server_timestamp || null,
  received_at: new Date().toISOString()
};
return msg;

const source_node_id = msg.topic || msg.nodeId || msg.source_node_id || '';
const raw_value = msg.payload;

// 1) opcua topic 정리
let normalized_source = String(source_node_id);
normalized_source = normalized_source.replace(/^ns=\d+;s=/, '');
normalized_source = normalized_source.replace(/;datatype=.*$/i, '');

// 2) 정규식 매칭
const m = normalized_source.match(
  /^DAS_LINE_(\d{2})_([A-Z]+)_(\d{2})_(vibration_rms|current_a|voltage_v|equipment_temperature_c)$/
);

if (!m) {
  node.warn({
    reason: 'sensor_node_id_not_matched',
    source_node_id,
    normalized_source
  });
  return null;
}

const line_no = Number(m[1]);
const equip_type = m[2];
const equip_no = Number(m[3]);
const sensor_field = m[4];

const equipment_type_base = {
  CAST: 100,
  CNC: 200,
  WASH: 300,
  ASSY: 400,
  TEST: 500
};

const equipment_id = (equipment_type_base[equip_type] || 0) + equip_no;
const line_id = line_no;

msg.topic = 'collect/sensor_leaf';
msg.payload = {
  collect_type: 'sensor_leaf',
  line_id,
  equipment_id,
  collect_line_name: `LINE-${String(line_no).padStart(2, '0')}`,
  collect_equipment_name: `${equip_type}-${String(equip_no).padStart(2, '0')}`,
  sensor_field,
  raw_value,
  source_node_id,
  normalized_source_node_id: normalized_source,
  datatype: (source_node_id.match(/;datatype=([^;]+)/i) || [null, null])[1],
  source_timestamp: msg.sourceTimestamp || msg.source_timestamp || null,
  server_timestamp: msg.serverTimestamp || msg.server_timestamp || null,
  received_at: new Date().toISOString()
};

return msg;

const payload = msg.payload || {};
if (payload.collect_type === 'line_payload') return [msg, null];
if (payload.collect_type === 'sensor_leaf') return [null, msg];
return null;

const input_payload = msg.payload || {};

function safe_json_parse(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  try { return JSON.parse(value); } catch (error) { return null; }
}
function to_number(value, default_value = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : default_value;
}
function to_boolean(value, default_value = false) {
  if (typeof value === 'boolean') return value;
  if (value === 1 || value === '1' || value === 'true') return true;
  if (value === 0 || value === '0' || value === 'false') return false;
  return default_value;
}
function build_invalid_core(line_id, equipment_id) {
  return {
    line_id,
    equipment_id,
    ts_epoch_ms: Date.now(),
    heartbeat: 0,
    quality_code: 0,
    power: false,
    status_code: 0,
    progress: 0,
    cycle_time: 0,
    part_count: 0,
    data_1_setpoint: 0,
    data_1_sensor: 0,
    data_2_setpoint: 0,
    data_2_sensor: 0,
    data_3_setpoint: 0,
    data_3_sensor: 0,
    cmd_id: 0,
    cmd_accepted: 0,
    cmd_status: 0
  };
}

const parsed_payload = safe_json_parse(input_payload.raw_payload);
let is_valid = true;
let invalid_reason = '';
let line_id = null;
let equipment_id = null;
let canonical_core = build_invalid_core(null, null);
let payload_parse_ok = false;

if (!parsed_payload || typeof parsed_payload !== 'object') {
  is_valid = false;
  invalid_reason = 'payload_json_parse_failed';
} else {
  payload_parse_ok = true;
  line_id = to_number(parsed_payload.line_id, null);
  equipment_id = to_number(parsed_payload.equipment_id, null);

  const has_required_fields =
    line_id !== null &&
    equipment_id !== null &&
    parsed_payload.ts_epoch_ms !== undefined &&
    parsed_payload.quality_code !== undefined &&
    parsed_payload.status_code !== undefined;

  if (!has_required_fields) {
    is_valid = false;
    invalid_reason = 'payload_missing_required_fields';
    canonical_core = build_invalid_core(line_id, equipment_id);
  } else {
    canonical_core = {
      line_id,
      equipment_id,
      ts_epoch_ms: to_number(parsed_payload.ts_epoch_ms, Date.now()),
      heartbeat: to_number(parsed_payload.heartbeat, 0),
      quality_code: to_number(parsed_payload.quality_code, 0),
      power: to_boolean(parsed_payload.power, false),
      status_code: to_number(parsed_payload.status_code, 0),
      progress: to_number(parsed_payload.progress, 0),
      cycle_time: to_number(parsed_payload.cycle_time, 0),
      part_count: to_number(parsed_payload.part_count, 0),
      data_1_setpoint: to_number(parsed_payload.data_1_setpoint, 0),
      data_1_sensor: to_number(parsed_payload.data_1_sensor, 0),
      data_2_setpoint: to_number(parsed_payload.data_2_setpoint, 0),
      data_2_sensor: to_number(parsed_payload.data_2_sensor, 0),
      data_3_setpoint: to_number(parsed_payload.data_3_setpoint, 0),
      data_3_sensor: to_number(parsed_payload.data_3_sensor, 0),
      cmd_id: to_number(parsed_payload.cmd_id, 0),
      cmd_accepted: to_number(parsed_payload.cmd_accepted, 0),
      cmd_status: to_number(parsed_payload.cmd_status, 0)
    };
  }
}

const snapshot_key = `${canonical_core.line_id}.${canonical_core.equipment_id}`;
const now_iso = new Date().toISOString();

msg.topic = 'canonical_input/core_payload';
msg.payload = {
  canonical_input_type: 'core_payload',
  is_valid,
  invalid_reason,
  snapshot_key,
  line_id: canonical_core.line_id,
  equipment_id: canonical_core.equipment_id,
  canonical_core,
  meta: {
    canonical_version: 'v1',
    schema_version: 'equipment_struct_v1',
    source: 'line_payload',
    source_node_id: input_payload.source_node_id,
    source_timestamp: input_payload.source_timestamp,
    server_timestamp: input_payload.server_timestamp,
    received_at: input_payload.received_at,
    processed_at: now_iso,
    collect_line_name: input_payload.collect_line_name || null,
    collect_equipment_name: input_payload.collect_equipment_name || null,
    payload_parse_ok,
    source_payload_raw: typeof input_payload.raw_payload === 'string' ? input_payload.raw_payload : JSON.stringify(input_payload.raw_payload ?? null)
  }
};

const last_core_payload_by_key = flow.get('last_core_payload_by_key') || {};
last_core_payload_by_key[snapshot_key] = RED.util.cloneMessage(msg.payload);
flow.set('last_core_payload_by_key', last_core_payload_by_key);

return msg;

function build_snapshot(core_payload, sensor_cache_by_key) {
  const input_payload = core_payload || {};
  const canonical_core = input_payload.canonical_core || {};
  const snapshot_key = input_payload.snapshot_key;
  const sensor_cache = sensor_cache_by_key[snapshot_key] || null;
  const now_ms = Date.now();
  const sensor_updated_ms = sensor_cache?.sensor_updated_at ? Date.parse(sensor_cache.sensor_updated_at) : null;
  const sensor_field_count = sensor_cache?.sensor_fields ? Object.keys(sensor_cache.sensor_fields).length : 0;

  return {
    canonical_type: 'canonical_snapshot',
    is_valid: !!input_payload.is_valid,
    invalid_reason: input_payload.invalid_reason || '',
    snapshot_key,
    core: {
      line_id: canonical_core.line_id,
      equipment_id: canonical_core.equipment_id,
      ts_epoch_ms: canonical_core.ts_epoch_ms,
      heartbeat: canonical_core.heartbeat,
      quality_code: canonical_core.quality_code,
      power: canonical_core.power,
      status_code: canonical_core.status_code,
      progress: canonical_core.progress,
      cycle_time: canonical_core.cycle_time,
      part_count: canonical_core.part_count,
      data_1_setpoint: canonical_core.data_1_setpoint,
      data_1_sensor: canonical_core.data_1_sensor,
      data_2_setpoint: canonical_core.data_2_setpoint,
      data_2_sensor: canonical_core.data_2_sensor,
      data_3_setpoint: canonical_core.data_3_setpoint,
      data_3_sensor: canonical_core.data_3_sensor,
      external_data_1_sensor: sensor_cache ? sensor_cache.external_data_1_sensor : null,
      external_data_2_sensor: sensor_cache ? sensor_cache.external_data_2_sensor : null,
      external_data_3_sensor: sensor_cache ? sensor_cache.external_data_3_sensor : null,
      external_data_4_sensor: sensor_cache ? sensor_cache.external_data_4_sensor : null,
      cmd_id: canonical_core.cmd_id,
      cmd_accepted: canonical_core.cmd_accepted,
      cmd_status: canonical_core.cmd_status
    },
    meta: {
      canonical_version: input_payload.meta?.canonical_version || 'v1',
      schema_version: input_payload.meta?.schema_version || 'equipment_struct_v1',
      source: input_payload.meta?.source || 'line_payload',
      collect_source_node_id: input_payload.meta?.source_node_id || null,
      collect_source_timestamp: input_payload.meta?.source_timestamp || null,
      collect_server_timestamp: input_payload.meta?.server_timestamp || null,
      collect_received_at: input_payload.meta?.received_at || null,
      canonical_processed_at: new Date().toISOString(),
      collect_line_name: input_payload.meta?.collect_line_name || sensor_cache?.meta?.collect_line_name || null,
      collect_equipment_name: input_payload.meta?.collect_equipment_name || sensor_cache?.meta?.collect_equipment_name || null,
      payload_parse_ok: input_payload.meta?.payload_parse_ok ?? false,
      source_payload_raw: input_payload.meta?.source_payload_raw || null,
      sensor_updated_at: sensor_cache?.sensor_updated_at || null,
      sensor_freshness_ms: Number.isFinite(sensor_updated_ms) ? Math.max(0, now_ms - sensor_updated_ms) : null,
      sensor_field_count,
      sensor_attached: sensor_field_count > 0,
      sensor_fields_present: sensor_cache?.sensor_fields ? Object.keys(sensor_cache.sensor_fields) : []
    }
  };
}

const sensor_cache_by_key = flow.get('sensor_cache_by_key') || {};
const merged_snapshot = build_snapshot(msg.payload, sensor_cache_by_key);
flow.set(`canonical_snapshot.${merged_snapshot.snapshot_key}`, merged_snapshot);
msg.topic = 'canonical/snapshot';
msg.payload = merged_snapshot;
return msg;

const input_payload = msg.payload || {};
const snapshot_key = input_payload.snapshot_key;
const last_core_payload_by_key = flow.get('last_core_payload_by_key') || {};
const core_payload = last_core_payload_by_key[snapshot_key] || null;

if (!core_payload) {
  msg.topic = 'canonical/snapshot/skipped';
  msg.payload = {
    reason: 'core_payload_not_available_yet',
    snapshot_key,
    sensor_field: input_payload.sensor_field,
    meta: input_payload.meta || {}
  };
  return [null, msg];
}

function build_snapshot(core_payload, sensor_cache_by_key) {
  const canonical_core = core_payload.canonical_core || {};
  const sensor_cache = sensor_cache_by_key[snapshot_key] || null;
  const now_ms = Date.now();
  const sensor_updated_ms = sensor_cache?.sensor_updated_at ? Date.parse(sensor_cache.sensor_updated_at) : null;
  const sensor_field_count = sensor_cache?.sensor_fields ? Object.keys(sensor_cache.sensor_fields).length : 0;

  return {
    canonical_type: 'canonical_snapshot',
    is_valid: !!core_payload.is_valid,
    invalid_reason: core_payload.invalid_reason || '',
    snapshot_key,
    core: {
      line_id: canonical_core.line_id,
      equipment_id: canonical_core.equipment_id,
      ts_epoch_ms: canonical_core.ts_epoch_ms,
      heartbeat: canonical_core.heartbeat,
      quality_code: canonical_core.quality_code,
      power: canonical_core.power,
      status_code: canonical_core.status_code,
      progress: canonical_core.progress,
      cycle_time: canonical_core.cycle_time,
      part_count: canonical_core.part_count,
      data_1_setpoint: canonical_core.data_1_setpoint,
      data_1_sensor: canonical_core.data_1_sensor,
      data_2_setpoint: canonical_core.data_2_setpoint,
      data_2_sensor: canonical_core.data_2_sensor,
      data_3_setpoint: canonical_core.data_3_setpoint,
      data_3_sensor: canonical_core.data_3_sensor,
      external_data_1_sensor: sensor_cache ? sensor_cache.external_data_1_sensor : null,
      external_data_2_sensor: sensor_cache ? sensor_cache.external_data_2_sensor : null,
      external_data_3_sensor: sensor_cache ? sensor_cache.external_data_3_sensor : null,
      external_data_4_sensor: sensor_cache ? sensor_cache.external_data_4_sensor : null,
      cmd_id: canonical_core.cmd_id,
      cmd_accepted: canonical_core.cmd_accepted,
      cmd_status: canonical_core.cmd_status
    },
    meta: {
      canonical_version: core_payload.meta?.canonical_version || 'v1',
      schema_version: core_payload.meta?.schema_version || 'equipment_struct_v1',
      source: core_payload.meta?.source || 'line_payload',
      collect_source_node_id: core_payload.meta?.source_node_id || null,
      collect_source_timestamp: core_payload.meta?.source_timestamp || null,
      collect_server_timestamp: core_payload.meta?.server_timestamp || null,
      collect_received_at: core_payload.meta?.received_at || null,
      canonical_processed_at: new Date().toISOString(),
      collect_line_name: core_payload.meta?.collect_line_name || sensor_cache?.meta?.collect_line_name || null,
      collect_equipment_name: core_payload.meta?.collect_equipment_name || sensor_cache?.meta?.collect_equipment_name || null,
      payload_parse_ok: core_payload.meta?.payload_parse_ok ?? false,
      source_payload_raw: core_payload.meta?.source_payload_raw || null,
      sensor_updated_at: sensor_cache?.sensor_updated_at || null,
      sensor_freshness_ms: Number.isFinite(sensor_updated_ms) ? Math.max(0, now_ms - sensor_updated_ms) : null,
      sensor_field_count,
      sensor_attached: sensor_field_count > 0,
      sensor_fields_present: sensor_cache?.sensor_fields ? Object.keys(sensor_cache.sensor_fields) : [],
      rebuild_trigger: 'sensor_update'
    }
  };
}

const sensor_cache_by_key = flow.get('sensor_cache_by_key') || {};
const merged_snapshot = build_snapshot(core_payload, sensor_cache_by_key);
flow.set(`canonical_snapshot.${snapshot_key}`, merged_snapshot);
msg.topic = 'canonical/snapshot';
msg.payload = merged_snapshot;
return [msg, null];

const input_payload = msg.payload || {};
const snapshot_key = `${input_payload.line_id}.${input_payload.equipment_id}`;
const sensor_cache_by_key = flow.get('sensor_cache_by_key') || {};
const now_iso = new Date().toISOString();

const current_cache = sensor_cache_by_key[snapshot_key] || {
  line_id: input_payload.line_id,
  equipment_id: input_payload.equipment_id,
  external_data_1_sensor: null,
  external_data_2_sensor: null,
  external_data_3_sensor: null,
  external_data_4_sensor: null,
  sensor_updated_at: null,
  sensor_fields: {},
  meta: {
    collect_line_name: input_payload.collect_line_name || null,
    collect_equipment_name: input_payload.collect_equipment_name || null,
    last_sensor_source_node_id: null,
    last_sensor_received_at: null
  }
};

function to_number_or_null(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

const field_map = {
  vibration_rms: 'external_data_1_sensor',
  current_a: 'external_data_2_sensor',
  voltage_v: 'external_data_3_sensor',
  equipment_temperature_c: 'external_data_4_sensor'
};

const mapped_field_name = field_map[input_payload.sensor_field] || null;
const sensor_value = mapped_field_name ? to_number_or_null(input_payload.raw_value) : null;

if (mapped_field_name) {
  current_cache[mapped_field_name] = sensor_value;
  current_cache.sensor_fields[input_payload.sensor_field] = {
    value: sensor_value,
    source_node_id: input_payload.source_node_id,
    source_timestamp: input_payload.source_timestamp,
    server_timestamp: input_payload.server_timestamp,
    received_at: input_payload.received_at,
    processed_at: now_iso
  };
  current_cache.sensor_updated_at = now_iso;
  current_cache.meta.collect_line_name = input_payload.collect_line_name || current_cache.meta.collect_line_name || null;
  current_cache.meta.collect_equipment_name = input_payload.collect_equipment_name || current_cache.meta.collect_equipment_name || null;
  current_cache.meta.last_sensor_source_node_id = input_payload.source_node_id || null;
  current_cache.meta.last_sensor_received_at = input_payload.received_at || null;
}

sensor_cache_by_key[snapshot_key] = current_cache;
flow.set('sensor_cache_by_key', sensor_cache_by_key);

msg.topic = 'canonical_input/sensor_cache';
msg.payload = {
  canonical_input_type: 'sensor_cache',
  snapshot_key,
  line_id: input_payload.line_id,
  equipment_id: input_payload.equipment_id,
  sensor_field: input_payload.sensor_field,
  sensor_value,
  sensor_cache: RED.util.cloneMessage(current_cache),
  meta: {
    source: 'sensor_leaf',
    source_node_id: input_payload.source_node_id,
    source_timestamp: input_payload.source_timestamp,
    server_timestamp: input_payload.server_timestamp,
    received_at: input_payload.received_at,
    processed_at: now_iso,
    collect_line_name: input_payload.collect_line_name || null,
    collect_equipment_name: input_payload.collect_equipment_name || null
  }
};
return msg;

function inferEquipmentType(equipmentId) {
    const id = Number(equipmentId);
    if (id >= 100 && id < 200) return 'CAST';
    if (id >= 200 && id < 300) return 'CNC';
    if (id >= 300 && id < 400) return 'WASH';
    if (id >= 400 && id < 500) return 'ASSY';
    if (id >= 500 && id < 600) return 'TEST';
    return null;
}

function toNullableNumber(value) {
    if (value === null || value === undefined || value === '') return null;
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function toNullableBoolean(value) {
    if (value === null || value === undefined || value === '') return null;
    if (typeof value === 'boolean') return value;
    if (value === 1 || value === '1' || value === 'true') return true;
    if (value === 0 || value === '0' || value === 'false') return false;
    return null;
}

function isInvalidEpochTs(tsEpochMs) {
    if (!Number.isFinite(tsEpochMs)) return true;
    if (tsEpochMs <= 0) return true;
    const iso = new Date(tsEpochMs).toISOString();
    return iso === '1970-01-01T00:00:00.000Z';
}

const snapshot = msg.payload || {};
const core = snapshot.core || {};
const raw = snapshot?.meta?.source_payload_raw ?? snapshot?.meta?.sourcepayloadraw;

if (snapshot.is_valid !== true && snapshot.isvalid !== true) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'skip invalid snapshot' });
    return null;
}

if (raw === '') {
    node.status({ fill: 'yellow', shape: 'ring', text: 'skip empty raw payload' });
    return null;
}

const tsEpochMs = toNullableNumber(core.ts_epoch_ms ?? core.tsepochms);
if (isInvalidEpochTs(tsEpochMs)) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'skip epoch/zero ts' });
    return null;
}

const ts = new Date(tsEpochMs).toISOString();
const lineIdRaw = core.line_id ?? core.lineid;
const equipmentIdRaw = core.equipment_id ?? core.equipmentid;
const lineId = lineIdRaw !== undefined && lineIdRaw !== null ? String(lineIdRaw) : null;
const equipmentId = equipmentIdRaw !== undefined && equipmentIdRaw !== null ? String(equipmentIdRaw) : null;

if (!lineId || !equipmentId) {
    node.warn({
        reason: 'tsdb batch skip: missing line/equipment id',
        snapshot_key: snapshot.snapshot_key ?? snapshot.snapshotkey ?? null
    });
    return null;
}

const equipmentType = inferEquipmentType(equipmentId);

msg.topic = 'equipment_snapshot.batch.row';
msg.payload = {
    ts,
    line_id: lineId,
    equipment_id: equipmentId,
    equipment_type: equipmentType,
    heartbeat: toNullableNumber(core.heartbeat),
    quality_code: toNullableNumber(core.quality_code ?? core.qualitycode),
    power: toNullableBoolean(core.power),
    status_code: toNullableNumber(core.status_code ?? core.statuscode),
    progress: toNullableNumber(core.progress),
    cycle_time: toNullableNumber(core.cycle_time ?? core.cycletime),
    part_count: toNullableNumber(core.part_count ?? core.partcount),
    data1_setpoint: toNullableNumber(core.data_1_setpoint ?? core.data1setpoint),
    data1_sensor: toNullableNumber(core.data_1_sensor ?? core.data1sensor),
    data2_setpoint: toNullableNumber(core.data_2_setpoint ?? core.data2setpoint),
    data2_sensor: toNullableNumber(core.data_2_sensor ?? core.data2sensor),
    data3_setpoint: toNullableNumber(core.data_3_setpoint ?? core.data3setpoint),
    data3_sensor: toNullableNumber(core.data_3_sensor ?? core.data3sensor),
    externaldata1_sensor: toNullableNumber(core.external_data_1_sensor ?? core.externaldata1sensor),
    externaldata2_sensor: toNullableNumber(core.external_data_2_sensor ?? core.externaldata2sensor),
    externaldata3_sensor: toNullableNumber(core.external_data_3_sensor ?? core.externaldata3sensor),
