    'cmd_id = EXCLUDED.cmd_id',
    'cmd_accepted = EXCLUDED.cmd_accepted',
    'cmd_status = EXCLUDED.cmd_status'
];

const valuesSql = [];
const params = [];
let p = 1;

for (const row of rows) {
    valuesSql.push(`($${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++}, $${p++})`);
    params.push(
        row.ts,
        row.line_id,
        row.equipment_id,
        row.equipment_type,
        row.heartbeat,
        row.quality_code,
        row.power,
        row.status_code,
        row.progress,
        row.cycle_time,
        row.part_count,
        row.data1_setpoint,
        row.data1_sensor,
