    equipment_id: equipmentId,
    ts_epoch_ms: tsEpochMs,
    heartbeat: toNumberOrDefault(core.heartbeat, 0),
    quality_code: toNumberOrDefault(core.quality_code ?? core.qualitycode, 0),
    power: toBoolAsInt(core.power),
    status_code: toNumberOrDefault(core.status_code ?? core.statuscode, 0),
    progress: toNumberOrDefault(core.progress, 0),
    cycle_time: toNumberOrDefault(core.cycle_time ?? core.cycletime, 0),
    part_count: toNumberOrDefault(core.part_count ?? core.partcount, 0),
    data1_setpoint: toNumberOrDefault(core.data_1_setpoint ?? core.data1setpoint, 0),
    data1_sensor: toNumberOrDefault(core.data_1_sensor ?? core.data1sensor, 0),
    data2_setpoint: toNumberOrDefault(core.data_2_setpoint ?? core.data2setpoint, 0),
    data2_sensor: toNumberOrDefault(core.data_2_sensor ?? core.data2sensor, 0),
    data3_setpoint: toNumberOrDefault(core.data_3_setpoint ?? core.data3setpoint, 0),
    data3_sensor: toNumberOrDefault(core.data_3_sensor ?? core.data3sensor, 0),
    externaldata1_sensor: toNumberOrDefault(core.external_data_1_sensor ?? core.externaldata1sensor, 0),
    externaldata2_sensor: toNumberOrDefault(core.external_data_2_sensor ?? core.externaldata2sensor, 0),
    externaldata3_sensor: toNumberOrDefault(core.external_data_3_sensor ?? core.externaldata3sensor, 0),
    externaldata4_sensor: toNumberOrDefault(core.external_data_4_sensor ?? core.externaldata4sensor, 0),
