const equipmentOrder = flow.get('udpEquipmentOrder') || [];
const cache = flow.get('udpEquipmentCache') || {};

function defaultRecord(lineId, equipmentId) {
    return {
        line_id: lineId,
        equipment_id: equipmentId,
        ts_epoch_ms: 0,
        heartbeat: 0,
        quality_code: 0,
        power: 0,
        status_code: 0,
        progress: 0,
        cycle_time: 0,
        part_count: 0,
        data1_setpoint: 0,
        data1_sensor: 0,
        data2_setpoint: 0,
        data2_sensor: 0,
        data3_setpoint: 0,
