function writeInt64LE(buf, value, offset) {
    const safe = Number.isFinite(Number(value)) ? BigInt(Math.trunc(Number(value))) : 0n;
    buf.writeBigInt64LE(safe, offset);
}

if (!equipmentOrder.length) {
    node.status({ fill: 'red', shape: 'ring', text: 'equipment order missing' });
    return null;
}

const PACKET_VERSION = 1;
const HEADER_SIZE = 16;
const RECORD_SIZE = 86;
const EQUIPMENT_COUNT = equipmentOrder.length;
const TOTAL_SIZE = HEADER_SIZE + (RECORD_SIZE * EQUIPMENT_COUNT);
const buf = Buffer.alloc(TOTAL_SIZE);

let offset = 0;
buf.write('TDAS', offset, 4, 'ascii'); offset += 4;
buf.writeUInt16LE(PACKET_VERSION, offset); offset += 2;
buf.writeUInt16LE(EQUIPMENT_COUNT, offset); offset += 2;
writeInt64LE(buf, Date.now(), offset); offset += 8;

let defaultFilled = 0;
for (const item of equipmentOrder) {
    const key = `${item.line_id}.${item.equipment_id}`;
    const record = cache[key] || defaultRecord(item.line_id, item.equipment_id);
    if (!cache[key]) defaultFilled += 1;

    buf.writeInt16LE(Number(record.line_id) || 0, offset); offset += 2;
    buf.writeInt16LE(Number(record.equipment_id) || 0, offset); offset += 2;
    writeInt64LE(buf, record.ts_epoch_ms, offset); offset += 8;
    buf.writeInt32LE(Number(record.heartbeat) || 0, offset); offset += 4;
    buf.writeInt16LE(Number(record.quality_code) || 0, offset); offset += 2;
    buf.writeUInt8(Number(record.power) ? 1 : 0, offset); offset += 1;
    buf.writeUInt8(0, offset); offset += 1;
    buf.writeInt16LE(Number(record.status_code) || 0, offset); offset += 2;
    buf.writeFloatLE(Number(record.progress) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.cycle_time) || 0, offset); offset += 4;
    buf.writeInt32LE(Number(record.part_count) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.data1_setpoint) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.data1_sensor) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.data2_setpoint) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.data2_sensor) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.data3_setpoint) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.data3_sensor) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.externaldata1_sensor) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.externaldata2_sensor) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.externaldata3_sensor) || 0, offset); offset += 4;
    buf.writeFloatLE(Number(record.externaldata4_sensor) || 0, offset); offset += 4;
    buf.writeInt32LE(Number(record.cmd_id) || 0, offset); offset += 4;
    buf.writeInt32LE(Number(record.cmd_accepted) || 0, offset); offset += 4;
    buf.writeInt32LE(Number(record.cmd_status) || 0, offset); offset += 4;
}

msg.payload = buf;
msg.ip = env.get('UDP_STREAM_HOST') || '127.0.0.1';
msg.port = Number(env.get('UDP_STREAM_PORT') || 50010);
msg.udpmeta = {
    packet_version: PACKET_VERSION,
    header_size: HEADER_SIZE,
    record_size: RECORD_SIZE,
    equipment_count: EQUIPMENT_COUNT,
    total_size: TOTAL_SIZE,
    default_filled_count: defaultFilled,
    destination_ip: msg.ip,
    destination_port: msg.port,
    sent_at: new Date().toISOString()
};

node.status({ fill: 'blue', shape: 'dot', text: `udp ${TOTAL_SIZE} bytes -> ${msg.ip}:${msg.port}` });
return msg;

const snapshot = msg.payload || {};
const core = snapshot.core || {};

function pad2(n) {
  return String(n).padStart(2, '0');
}

function infer_equipment_type(equipment_id) {
  const id = Number(equipment_id);
  if (id >= 100 && id < 200) return 'CAST';
  if (id >= 200 && id < 300) return 'CNC';
  if (id >= 300 && id < 400) return 'WASH';
  if (id >= 400 && id < 500) return 'ASSY';
  if (id >= 500 && id < 600) return 'TEST';
  return 'UNKNOWN';
}

function infer_equipment_no(equipment_id) {
  return Number(equipment_id) % 100;
}

function to_line_token(line_id) {
  return `LINE${pad2(line_id)}`;
}

function to_equipment_token(equipment_type, equipment_no) {
  return `${equipment_type}${pad2(equipment_no)}`;
}

function to_legacy_status(status_code, power) {
  if (!power) return 'OFF';
  switch (Number(status_code)) {
    case 0: return 'IDLE';
    case 1: return 'RUN';
    case 2: return 'COMPLETED';
    case 3: return 'WARNING';
    case 4: return 'ERROR';
    default: return 'UNKNOWN';
  }
}

function toDoubleOrZero(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function addVar(out, nodeName, datatype, value) {
  out.push({
    topic: `ns=2;s=${nodeName}`,
    datatype,
    payload: value
  });
}

function addAliasAndScoped(out, aliasBase, scopedBase, suffix, datatype, value) {
  addVar(out, `${aliasBase}.${suffix}`, datatype, value);
  addVar(out, `${scopedBase}.${suffix}`, datatype, value);
}

const line_id = Number(core.line_id);
const equipment_id = Number(core.equipment_id);
const equipment_type = infer_equipment_type(equipment_id);
const equipment_no = infer_equipment_no(equipment_id);

if (!Number.isFinite(line_id) || !Number.isFinite(equipment_id) || equipment_type === 'UNKNOWN') {
  node.warn({
    reason: 'legacy_ns2_invalid_equipment_identity',
    line_id,
    equipment_id,
    snapshot_key: snapshot.snapshot_key || null
  });
  return null;
}

const lineToken = to_line_token(line_id);
const eqToken = to_equipment_token(equipment_type, equipment_no);
const aliasBase = eqToken;
const scopedBase = `${lineToken}.${eqToken}`;

const dataNameMap = {
  CAST: ['InjectionPressure', 'MoldTemperature', 'CoolingFlow'],
  CNC: ['SpindleSpeed', 'ToolUsage', 'CoolantFlow'],
  WASH: ['CleaningConcentration', 'CleaningTemperature', 'CleaningPressure'],
  ASSY: ['TighteningTorque', 'TighteningAngle', 'PressForce'],
  TEST: ['BoreDimension', 'HoleDimension', 'ResultOk']
};

const dataNames = dataNameMap[equipment_type];
const out = [];
const legacyStatus = to_legacy_status(core.status_code, core.power);
const payloadJson = JSON.stringify(snapshot);

addAliasAndScoped(out, aliasBase, scopedBase, 'AlarmCode', 'Int32', Number(core.status_code || 0));
addAliasAndScoped(out, aliasBase, scopedBase, 'CycleTime', 'Double', toDoubleOrZero(core.cycle_time));
addAliasAndScoped(out, aliasBase, scopedBase, 'Payload', 'String', payloadJson);
addAliasAndScoped(out, aliasBase, scopedBase, 'SensorCurrent', 'Double', toDoubleOrZero(core.external_data_2_sensor));
addAliasAndScoped(out, aliasBase, scopedBase, 'SensorTemperature', 'Double', toDoubleOrZero(core.external_data_4_sensor));
addAliasAndScoped(out, aliasBase, scopedBase, 'SensorVibration', 'Double', toDoubleOrZero(core.external_data_1_sensor));
addAliasAndScoped(out, aliasBase, scopedBase, 'SensorVoltage', 'Double', toDoubleOrZero(core.external_data_3_sensor));
addAliasAndScoped(out, aliasBase, scopedBase, 'Status', 'String', legacyStatus);

if (equipment_type === 'TEST') {
  addAliasAndScoped(out, aliasBase, scopedBase, dataNames[0], 'Double', toDoubleOrZero(core.data_1_sensor));
  addAliasAndScoped(out, aliasBase, scopedBase, dataNames[1], 'Double', toDoubleOrZero(core.data_2_sensor));
  addAliasAndScoped(out, aliasBase, scopedBase, dataNames[2], 'Boolean', !!core.data_3_sensor);
} else {
  addAliasAndScoped(out, aliasBase, scopedBase, dataNames[0], 'Double', toDoubleOrZero(core.data_1_sensor));
  addAliasAndScoped(out, aliasBase, scopedBase, dataNames[1], 'Double', toDoubleOrZero(core.data_2_sensor));
  addAliasAndScoped(out, aliasBase, scopedBase, dataNames[2], 'Double', toDoubleOrZero(core.data_3_sensor));
}

msg.topic = 'legacy_ns2/publish_batch';
msg.payload = out;
msg.legacy_ns2_meta = {
  snapshot_key: snapshot.snapshot_key || null,
  line_id,
  equipment_id,
  equipment_type,
  equipment_no,
  aliasBase,
  scopedBase,
  publish_count: out.length
};

return msg;

