    payload: { opcuaCommand: 'addVariable' },
    ns3_meta: Object.assign({}, msg.ns3_meta || {}, {
      stage: 'register',
      variableName,
      datatype,
      forceRegister
    })
  });
  registered[variableName] = true;
}

serverMessages.push({
  payload: {
    messageType: 'Variable',
    namespace,
    variableName,
    variableValue: payload,
