function toNullableNumber(value) {
    if (value === null || value === undefined || value === "") return null;
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function toNullableBoolean(value) {
    if (value === null || value === undefined || value === "") return null;
    if (typeof value === "boolean") return value;
    if (value === 1 || value === "1" || value === "true") return true;
    if (value === 0 || value === "0" || value === "false") return false;
    return null;
}

function mapCommandStatus(accepted, cmdStatus) {
    const a = toNullableBoolean(accepted);
    const s = toNullableNumber(cmdStatus);

    if (a === false) return "REJECTED";
    if (a === null && s === null) return "UNKNOWN";
    if (a === true && s === 0) return "ACCEPTED";
    if (a === true && s === 1) return "RUNNING";
    if (a === true && s === 2) return "COMPLETED";
    if (a === true && s === 3) return "ERROR";
    if (a === false && s === 0) return "REJECTED";
    return "UNKNOWN";
}

const snapshot = msg.payload;
const core = snapshot?.core || null;
const raw = snapshot?.meta?.sourcepayloadraw;

if (!snapshot || snapshot.isvalid !== true) {
    node.status({ fill: "yellow", shape: "ring", text: "skip invalid snapshot" });
    return null;
}

if (!raw) {
    node.status({ fill: "yellow", shape: "ring", text: "skip empty raw payload" });
    return null;
}

const lineId = toNullableNumber(core?.lineid);
const equipmentId = toNullableNumber(core?.equipmentid);
const commandIdNum = toNullableNumber(core?.cmdid);
const accepted = toNullableBoolean(core?.cmdaccepted);
const cmdStatus = toNullableNumber(core?.cmdstatus);
const sourceTsEpochMs = toNullableNumber(core?.tsepochms);

if (lineId === null || equipmentId === null) {
    node.warn({
        reason: "command-response-skip-missing-identity",
        snapshotkey: snapshot?.snapshotkey || null,
        lineId,
        equipmentId
    });
    return null;
}

if (commandIdNum === null || commandIdNum === 0) {
    node.status({ fill: "grey", shape: "ring", text: `${lineId}.${equipmentId} - no cmdid` });
    return null;
}

const commandId = String(commandIdNum);
const status = mapCommandStatus(accepted, cmdStatus);
const observedAt = sourceTsEpochMs !== null
    ? new Date(sourceTsEpochMs).toISOString()
    : new Date().toISOString();

const responseJsonObj = {
    snapshotkey: snapshot?.snapshotkey || null,
    canonicalprocessedat: snapshot?.meta?.canonicalprocessedat || null,
    source: snapshot?.meta?.source || null,
    collectsourcenodeid: snapshot?.meta?.collectsourcenodeid || snapshot?.meta?.sourcenodeid || null,
    collectreceivedat: snapshot?.meta?.collectreceivedat || snapshot?.meta?.receivedat || null,
    lineid: lineId,
    equipmentid: equipmentId,
    cmdid: commandIdNum,
    cmdaccepted: accepted,
    cmdstatus: cmdStatus
};

const responseJson = JSON.stringify(responseJsonObj);
const snapshotKey = snapshot?.snapshotkey || `${lineId}.${equipmentId}`;
const sourceNodeId = snapshot?.meta?.collectsourcenodeid || snapshot?.meta?.sourcenodeid || null;

const cacheKey = `${lineId}.${equipmentId}`;
const latestCache = flow.get("commandLatestCacheByEquipment") || {};
const prev = latestCache[cacheKey] || null;

const fingerprint = JSON.stringify({
    commandId,
    accepted,
    cmdStatus,
    status
});

const changed = !prev || prev.fingerprint !== fingerprint;

latestCache[cacheKey] = {
    commandId,
    accepted,
    cmdStatus,
    status,
    fingerprint,
    updatedAt: new Date().toISOString()
};
flow.set("commandLatestCacheByEquipment", latestCache);

const latestMsg = RED.util.cloneMessage(msg);
latestMsg.topic = "command.latest.upsert";
latestMsg.payload = {
    query: `
INSERT INTO public.command_latest_response (
    line_id,
    equipment_id,
    command_id,
    command_type,
    status,
    accepted,
    cmd_status,
    response_json,
    source_tsepochms,
    first_observed_at,
    updated_at,
    snapshot_key,
    source_node_id,
    last_error
) VALUES (
    $1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,
    COALESCE($10::timestamptz, now()),
    now(),
    $11,$12,$13
)
ON CONFLICT (line_id, equipment_id)
DO UPDATE SET
    command_id = EXCLUDED.command_id,
    command_type = EXCLUDED.command_type,
    status = EXCLUDED.status,
    accepted = EXCLUDED.accepted,
    cmd_status = EXCLUDED.cmd_status,
    response_json = EXCLUDED.response_json,
    source_tsepochms = EXCLUDED.source_tsepochms,
    updated_at = now(),
    snapshot_key = EXCLUDED.snapshot_key,
    source_node_id = EXCLUDED.source_node_id,
    last_error = EXCLUDED.last_error
`,
    params: [
        lineId,
        equipmentId,
        commandId,
        null,
        status,
        accepted,
        cmdStatus,
        responseJson,
        sourceTsEpochMs,
        observedAt,
        snapshotKey,
        sourceNodeId,
        null
    ],
    querymode: "upsert",
    lineid: lineId,
    equipmentid: equipmentId,
    commandid: commandId,
    changed,
    snapshotkey: snapshotKey
};

let eventMsg = null;

if (changed) {
    eventMsg = RED.util.cloneMessage(msg);
    eventMsg.topic = "command.event.insert";
    eventMsg.payload = {
        query: `
INSERT INTO public.command_response_event (
    command_id,
    line_id,
    equipment_id,
    accepted,
    cmd_status,
    status,
    response_json,
    source_tsepochms,
    observed_at,
    snapshot_key,
    source_node_id,
    last_error
) VALUES (
    $1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9::timestamptz,$10,$11,$12
)
`,
        params: [
            commandId,
            lineId,
            equipmentId,
            accepted,
            cmdStatus,
            status,
            responseJson,
            sourceTsEpochMs,
            observedAt,
            snapshotKey,
            sourceNodeId,
            null
        ],
        querymode: "insert",
        lineid: lineId,
        equipmentid: equipmentId,
        commandid: commandId,
        changed,
        snapshotkey: snapshotKey
    };
}

node.status({
    fill: changed ? "green" : "blue",
    shape: "dot",
    text: `${lineId}.${equipmentId} cmd=${commandId} ${changed ? "latest+event" : "latest-only"}`
});

return [latestMsg, eventMsg];

msg.commandlatestmeta = {
